class _C:
    ops = 0

    def __init__(self, v):
        self.v = v

    def __eq__(self, other):
        _C.ops += 1
        return isinstance(other, _C) and self.v == other.v

    def __hash__(self):
        _C.ops += 1
        return hash(self.v)

a = [_C(i) for i in range(400)]
b = [_C(i) for i in range(200, 600)]
_C.ops = 0
result = common_items(a, b)
assert [x.v for x in result] == list(range(200, 400))
assert _C.ops < 4000, f'common_items made {_C.ops} comparisons and hash computations for 400 + 400 items; build one lookup structure, once, then check each item of b against it'

