class _C:
    ops = 0

    def __init__(self, v):
        self.v = v

    def __eq__(self, other):
        _C.ops += 1
        return isinstance(other, _C) and self.v == other.v

    def __hash__(self):
        _C.ops += 1
        return hash(self.v)

items = [_C(i) for i in range(1000)] + [_C(500)]
_C.ops = 0
result = first_repeat(items)
assert result is not None and result.v == 500
assert _C.ops < 5000, f'first_repeat made {_C.ops} comparisons and hash computations; remember what you have seen in a set'

class _C:
    ops = 0

    def __init__(self, v):
        self.v = v

    def __eq__(self, other):
        _C.ops += 1
        return isinstance(other, _C) and self.v == other.v

    def __hash__(self):
        _C.ops += 1
        return hash(self.v)

def _ops(n):
    items = [_C(i) for i in range(n)]
    _C.ops = 0
    first_repeat(items)
    return _C.ops
small, big = _ops(400), _ops(800)
assert big <= 3 * small, f'doubling the input took the work from {small} to {big} operations'

steps.solution:
def first_repeat(items):
    seen = set()
    for item in items:
        if item in seen:
            return item
        seen.add(item)
    return None
